-- ═════════════════════════════════════════════════════════════════════════════════════════════
-- Hand-written part (Prisma cannot express it): RLS, partial unique index, CHECKs, triggers.
-- Constraint, index, function and trigger names below are part of the migration contract (tests/db/phase6-schema.test.ts).
-- The generic guards leadro_append_only (Phase 2), leadro_immutable_columns and leadro_no_delete (Phase 4) are reused as they are.
-- The four analytics indexes on Job, Lead and LeadRecoveryCase above are justified in DECISIONS.md "Phase 6 Task 1".
-- ═════════════════════════════════════════════════════════════════════════════════════════════

-- ───────────── Row-level security ─────────────
-- Same fail-closed DO-block as Phase 1-5: every table with a "tenantId" column (the 3 new ones included)
-- is ENABLEd + FORCEd and gets the tenant_isolation policy. Re-running it is idempotent.
DO $$
DECLARE
  t record;
BEGIN
  FOR t IN
    SELECT c.table_name
    FROM information_schema.columns c
    JOIN information_schema.tables tb
      ON tb.table_schema = c.table_schema AND tb.table_name = c.table_name AND tb.table_type = 'BASE TABLE'
    WHERE c.table_schema = 'public' AND c.column_name = 'tenantId'
  LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t.table_name);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t.table_name);
    EXECUTE format('DROP POLICY IF EXISTS tenant_isolation ON %I', t.table_name);
    EXECUTE format(
      'CREATE POLICY tenant_isolation ON %I USING ("tenantId" = (SELECT NULLIF(current_setting(''app.tenant_id'', true), ''''))) WITH CHECK ("tenantId" = (SELECT NULLIF(current_setting(''app.tenant_id'', true), '''')))',
      t.table_name
    );
  END LOOP;
END
$$;

-- ───────────── Shared shape rules of report columns ─────────────
-- A column list is 1-200 distinct column keys (identifier-like, e.g. "scheduledStartAt", "customer.name"), no NULL entries.
-- Whether a key exists in the dataset and may be shown to the caller is decided by the service (dataset catalog + field sets).
CREATE OR REPLACE FUNCTION leadro_report_columns_valid(cols text[]) RETURNS boolean
LANGUAGE sql IMMUTABLE AS $$
  SELECT cols IS NOT NULL
    AND cardinality(cols) BETWEEN 1 AND 200
    AND array_position(cols, NULL) IS NULL
    AND NOT EXISTS (SELECT 1 FROM unnest(cols) AS c WHERE c !~ '^[A-Za-z][A-Za-z0-9_.]{0,63}$')
    AND cardinality(cols) = (SELECT count(DISTINCT c) FROM unnest(cols) AS c)
$$;

-- ───────────── Saved report views ─────────────
ALTER TABLE "SavedReportView" ADD CONSTRAINT saved_report_view_name_present
  CHECK (length(btrim("name")) BETWEEN 1 AND 120);
ALTER TABLE "SavedReportView" ADD CONSTRAINT saved_report_view_dataset_key_format
  CHECK ("datasetKey" ~ '^[a-z][a-z0-9_]{0,62}$');
ALTER TABLE "SavedReportView" ADD CONSTRAINT saved_report_view_columns_valid CHECK (leadro_report_columns_valid("columns"));
ALTER TABLE "SavedReportView" ADD CONSTRAINT saved_report_view_filters_object CHECK (jsonb_typeof("filters") = 'object');
-- Archiving names who archived; both are set or cleared together.
ALTER TABLE "SavedReportView" ADD CONSTRAINT saved_report_view_archived
  CHECK (("archivedAt" IS NULL) = ("archivedById" IS NULL));
-- One active view per owner and name (case- and edge-space-insensitive); an archived name can be reused.
CREATE UNIQUE INDEX saved_report_view_owner_name_active
  ON "SavedReportView" ("tenantId", "ownerId", lower(btrim("name"))) WHERE "archivedAt" IS NULL;
-- The owner and the dataset never change: another dataset is another view, and a view is never handed to someone else
-- (sharing is by role, through SavedReportViewShare).
CREATE TRIGGER saved_report_view_immutable
  BEFORE UPDATE ON "SavedReportView"
  FOR EACH ROW EXECUTE FUNCTION leadro_immutable_columns('tenantId', 'ownerId', 'datasetKey', 'createdAt');
CREATE TRIGGER saved_report_view_no_delete BEFORE DELETE ON "SavedReportView" FOR EACH ROW EXECUTE FUNCTION leadro_no_delete();

-- ───────────── Saved view shares ─────────────
-- A share is inserted or deleted (unshare, audited by the service), never edited.
CREATE TRIGGER saved_report_view_share_immutable
  BEFORE UPDATE ON "SavedReportViewShare"
  FOR EACH ROW EXECUTE FUNCTION leadro_immutable_columns('id', 'tenantId', 'viewId', 'roleId', 'sharedById', 'createdAt');

-- ───────────── Report exports (append-only log) ─────────────
ALTER TABLE "ReportExport" ADD CONSTRAINT report_export_dataset_key_format
  CHECK ("datasetKey" ~ '^[a-z][a-z0-9_]{0,62}$');
ALTER TABLE "ReportExport" ADD CONSTRAINT report_export_columns_valid CHECK (leadro_report_columns_valid("columns"));
ALTER TABLE "ReportExport" ADD CONSTRAINT report_export_filters_object CHECK (jsonb_typeof("filters") = 'object');
ALTER TABLE "ReportExport" ADD CONSTRAINT report_export_filters_hash_format CHECK ("filtersHash" ~ '^[0-9a-f]{64}$');
ALTER TABLE "ReportExport" ADD CONSTRAINT report_export_row_limit_positive CHECK ("rowLimit" > 0);
-- The row count tells the truth about the outcome: a completed export wrote at most the cap, a refused one found more than the
-- cap, a failed one may not have counted at all.
ALTER TABLE "ReportExport" ADD CONSTRAINT report_export_row_count_matches_status CHECK (
  ("rowCount" IS NULL OR "rowCount" >= 0)
  AND CASE "status"
    WHEN 'COMPLETED' THEN "rowCount" IS NOT NULL AND "rowCount" <= "rowLimit"
    WHEN 'REFUSED_TOO_LARGE' THEN "rowCount" IS NOT NULL AND "rowCount" > "rowLimit"
    ELSE true
  END
);
-- A failure is recorded as a stable code (never an internal message, stack trace or SQL), and only for FAILED.
ALTER TABLE "ReportExport" ADD CONSTRAINT report_export_failure_code CHECK (
  ("status" = 'FAILED') = ("failureCode" IS NOT NULL)
  AND ("failureCode" IS NULL OR "failureCode" ~ '^[a-z][a-z0-9_]{0,62}$')
);
-- The export log is append-only, like the audit log.
CREATE TRIGGER report_export_no_update_delete
  BEFORE UPDATE OR DELETE ON "ReportExport"
  FOR EACH ROW EXECUTE FUNCTION leadro_append_only();
CREATE TRIGGER report_export_no_truncate
  BEFORE TRUNCATE ON "ReportExport"
  FOR EACH STATEMENT EXECUTE FUNCTION leadro_append_only();
